/**
 * The shipped assets are exactly the four sound cues and the share fallback image, every 'assets/...' path the code names
 * exists, they are generated by scripts in tools/, and the package ignore list does not strip them.
 */
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { generate } = require('../tools/gen-share-fallback');

const GAME = path.join(__dirname, '..');
const ASSETS = path.join(GAME, 'assets');

function walk(dir, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(path.relative(ASSETS, p).split(path.sep).join('/'));
  }
  return out;
}

test('assets/ holds exactly the four sound cues and share-fallback.png', () => {
  assert.deepStrictEqual(walk(ASSETS, []).sort(), ['share-fallback.png', 'sounds/flip.wav', 'sounds/loss.wav', 'sounds/pick.wav', 'sounds/win.wav']);
});

test('every assets/... path named in the shipped js exists', () => {
  const missing = [];
  (function scan(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (['tests', 'tools', 'node_modules', 'assets'].includes(e.name)) continue;
      const p = path.join(dir, e.name);
      if (e.isDirectory()) scan(p);
      else if (e.name.endsWith('.js')) {
        const src = fs.readFileSync(p, 'utf8');
        for (const m of src.matchAll(/'(assets\/[A-Za-z0-9_\/.-]+)'/g)) if (!fs.existsSync(path.join(GAME, m[1]))) missing.push(path.relative(GAME, p) + ': ' + m[1]);
        // the sound cues are built from a name: assets/sounds/<name>.wav
        if (/'assets\/sounds\/' \+ name \+ '\.wav'/.test(src)) for (const n of require('../js/audio').CUES) if (!fs.existsSync(path.join(ASSETS, 'sounds', n + '.wav'))) missing.push('sounds/' + n + '.wav');
      }
    }
  })(GAME);
  assert.deepStrictEqual(missing, []);
});

test('share-fallback.png: valid 500x400 (5:4) RGB PNG, small, equal to tools/gen-share-fallback.js output, path matches js/share.js', () => {
  const buf = fs.readFileSync(path.join(ASSETS, 'share-fallback.png'));
  assert.ok(buf.equals(generate()), 'run node tools/gen-share-fallback.js');
  assert.strictEqual(buf.toString('hex', 0, 8), '89504e470d0a1a0a');
  assert.strictEqual(buf.readUInt32BE(16), 500);
  assert.strictEqual(buf.readUInt32BE(20), 400);
  assert.ok(buf.length < 32 * 1024, 'small: ' + buf.length);
  assert.strictEqual(require('../js/share').FALLBACK_IMAGE, 'assets/share-fallback.png');
  assert.match(fs.readFileSync(path.join(GAME, 'js', 'share.js'), 'utf8'), /const FALLBACK_IMAGE = 'assets\/share-fallback\.png';/);
});

test('the package ignore list keeps assets/ (only tests, tools, node_modules, deploy folders and dev files are stripped)', () => {
  const cfg = JSON.parse(fs.readFileSync(path.join(GAME, 'project.config.json'), 'utf8'));
  for (const i of cfg.packOptions.ignore) assert.ok(!/^assets(\/|$)/.test(i.value), 'assets must ship: ' + i.value);
});

test('the share fallback carries no daily spoiler: the generator never reads a seed, a result or the content', () => {
  const src = fs.readFileSync(path.join(GAME, 'tools', 'gen-share-fallback.js'), 'utf8');
  assert.ok(!/require\('\.\.\/core|seed|lineup/i.test(src.replace(/\/\*[\s\S]*?\*\//, '')));
});
